INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (4, 'antonio-petra', 'Antonio', 'Petra', 'Marketing Strategy & Innovation Specialist', '<p>Marketing strategy and innovation specialist with experience across strategy, data, insight and marketing roles.</p>', '{}', 'Strategy Director at VML South Africa; Marketing Strategy & Innovation Specialist; Head of Strategy, Data & Innovation at FCB Africa; Digital Marketing, Innovation and Data Director – ABSA Barclays Unit at FCB; Head of Marketing and Business Development at Rocksteady; Head of Strategy & Insight at NATIVE VML; Head of Analytics & Insight at Comnenter; Marketing Manager at AMI Financial Services', NULL, 'antonio.petra@vml.com', 'approved', '2025-11-22T13:55:47.527192+00:00', '2025-11-22T13:55:47.257+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (6, 'parusha-partab', 'Parusha', 'Partab', 'Chief Strategy Officer (CSO)', '<p>Chief Strategy Officer at VML South Africa with extensive experience across digital innovation, brand strategy, customer experience, and integrated communications. Formerly held senior strategy roles across leading agencies and digital groups, contributing to strategy leadership across African markets and global brands.</p>', '{}', 'Chief Strategy Officer (CSO) at VML (Apr 2022 - Present); Head of IAB SA DEI Council at IAB South Africa (Nov 2023 - Present); Transformation Council & Women''s Council Member at IAB South Africa (Apr 2022 - Oct 2023); Group Strategy Director at Wunderman Thompson South Africa (Apr 2022 - Jan 2024); Strategy Director at Wunderman Thompson South Africa (Oct 2020 - Apr 2022); Head of Strategy at Squad Digital (Apr 2019 - Nov 2020); Managing Director at Strategy & Co (Feb 2018 - Nov 2020); Head of Strategy at Creative Spark (Mar 2018 - Mar 2019); Senior Strategist at Joe Public United (May 2016 - Feb 2018); Digital Strategist at NXT Digital Innovation (Apr 2014 - Feb 2016); Creative Strategist at DOTNXT (Sep 2013 - Feb 2014); Intern at NATIVE VML (2013)', NULL, 'parusha.partab@vml.com', 'approved', '2025-11-22T14:11:33.194564+00:00', '2025-11-22T14:11:32.891+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (7, 'avron-berkman', 'Avron', 'Berkman', 'Chief Financial Officer', '<p>Chief Financial Officer with extensive experience across executive management, contract negotiation, financial leadership and consulting roles in South Africa.</p>', '{}', 'Chief Financial Officer at VML (Jul 2014 - Present); Consulting CFO at Multisun Pty (Ltd) (Dec 2013 - Jun 2014); Chief Financial Officer at Moyo (Mar 2003 - Sep 2013); Managing Director at Vikon Valiant (Jun 2000 - Dec 2002); Financial Director at Automa Multi Styrene (Pty) Ltd (Oct 1993 - May 2000)', NULL, 'avron.berkman@vml.com', 'approved', '2025-11-22T14:15:02.73899+00:00', '2025-11-22T14:15:02.037+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (8, 'unati-moalusi', 'Unati', 'Moalusi', 'Chief People Officer', '<p>Chief People Officer at VML with a background as a Counselling Psychologist, HR practitioner and Consciousness Coach®. Focused on empowering people to make conscious and authentic decisions, with a deep understanding of human behaviour and organisational culture.</p>', '{}', 'Chief People Officer at VML (Jan 2024 - Present); Chief People Officer at Wunderman South Africa (Oct 2018 - Jan 2024); Senior HR Business Partner at Hollard Insurance (Nov 2011 - Jun 2018); Performance Consultant at The Performance Hub (May 2010 - Oct 2011); Counselling Psychologist & Consultant at Centre for the Study of Violence and Reconciliation (Jan 2007 - Apr 2010)', NULL, 'unati.moalusi@vml.com', 'approved', '2025-11-22T19:23:20.039684+00:00', '2025-11-22T19:23:19.633+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (9, 'fran-luckin', 'Fran', 'Luckin', 'Chief Creative Officer', '<p>Chief Creative Officer at VML South Africa with a long career in creative leadership across major South African agencies. Has held senior creative roles at Ogilvy, Quirk and Grey, and began her career at The Jupiter Drawing Room and TBWA/Hunt Lascaris.</p>', '{}', 'Chief Creative Officer at VML (Feb 2024 - Present); Chief Creative Officer at Grey Africa (Feb 2016 - Mar 2024); Executive Creative Director at Quirk (Jul 2013 - Jan 2015); Executive Creative Director at Ogilvy & Mather (Oct 2008 - Jun 2013); Creative Director at TBWA Hunt Lascaris Johannesburg (Feb 1999 - Oct 2003); Began career at The Jupiter Drawing Room (dates not listed)', NULL, 'fran.luckin@vml.com', 'approved', '2025-11-22T19:25:06.872549+00:00', '2025-11-22T19:25:06.551+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (10, 'insaaf-khan', 'Insaaf', 'Khan', 'Chief Client Officer', '<p>Chief Client Officer at VML South Africa with extensive experience across client engagement, growth leadership, and account management roles in leading agencies.</p>', '{}', 'Chief Client Officer at VML (Oct 2025 - Present); Chief Growth Officer at VML (Apr 2020 - Present); Chief Growth Officer at VML (May 2024 - Oct 2025); Client Engagement at VML (Aug 2016 - Apr 2020); Senior Account Director at M&C Saatchi Abel (Mar 2014 - Jul 2016); Account Manager at ninety9cents (Aug 2012 - Aug 2013); Account Executive at Singh & Sons Advertising Agency (Aug 2011 - Jul 2012); Line Producer & Company Production Manager at The Fort (Jan 2009 - Dec 2010)', NULL, 'insaaf.khan@vml.com', 'approved', '2025-11-22T19:26:31.040212+00:00', '2025-11-22T19:26:30.901+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (11, 'danelle-stiles', 'Danelle', 'Stiles', 'Chief Operating Officer', '<p>Chief Operating Officer at VML South Africa with deep experience in operations, project management, leadership and delivery across multiple senior roles over more than 15 years at VML and NATIVE VML.</p>', '{}', 'Chief Operating Officer at VML (Sep 2025 - Present); Group Managing Director at VML (Apr 2024 - Sep 2025); Managing Director at VML (Jan 2018 - Sep 2025); Operations Director at VML (Mar 2015 - Dec 2017); Head of Projects at VML (2010 - Mar 2015); Head of Project Management at NATIVE VML (2007 - 2009); Project Manager at NATIVE VML (2005 - 2007); Front End Developer at NATIVE VML / Cambrient (2002 - 2006)', NULL, 'danelle.stiles@vml.com', 'approved', '2025-11-26T08:22:17.834681+00:00', '2025-11-26T08:22:17.635+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
INSERT INTO profiles (id, slug, first_name, last_name, job_title, description_html, clients, experience, photo_url, email, status, created_at, updated_at) VALUES (12, 'nhlanhla-ngcobo', 'Nhlanhla', 'Ngcobo', 'Executive Creative Director', '<p>Executive Creative Director at VML South Africa with extensive creative leadership experience across major agencies. Background spans creative direction, copywriting, conceptual development, performance, and artistic work across multiple brands and platforms.</p>', '{}', 'Board Member at Creative Circle South Africa (Jan 2025 - Present); Executive Creative Director at VML South Africa (Sep 2023 - Present); Creative Director at M&C Saatchi Abel (Feb 2021 - Sep 2023); Creative Director at BIG FKN GUN (Jan 2010 - Sep 2023); Creative Director at Anheuser-Busch InBev Africa / Draftline (Mar 2020 - Feb 2021); Creative Director at FCB Global (2019 - Mar 2020); Senior Copywriter at Ogilvy Johannesburg (Jan 2016 - Jan 2017); Creative Group Head at Ogilvy Johannesburg (Jun 2016 - Apr 2018); Copywriter at Black River FC (Nov 2010 - Oct 2014); Junior Copywriter at The Jupiter Drawing Room (May 2009 - May 2010); Published Poet in Nocturnal Nuances (Jan 2003 - Feb 2003)', NULL, 'nhlanhla.ngcobo@vml.com', 'approved', '2025-11-26T09:42:38.563093+00:00', '2025-11-26T09:42:38.333+00:00') ON CONFLICT (slug) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, job_title = EXCLUDED.job_title, description_html = EXCLUDED.description_html, clients = EXCLUDED.clients, experience = EXCLUDED.experience, photo_url = EXCLUDED.photo_url, email = EXCLUDED.email, status = EXCLUDED.status, updated_at = EXCLUDED.updated_at;
