INSERT INTO policy_embeddings (id, policy_id, policy_slug, chunk_index, content, embedding, created_at) VALUES (188, '3b511330-0a67-4284-8378-d2ed534894b4', 'business-structure', 1, 'The Client Triad Each client pod is led by a triad of leaders that represent the core disciplines needed to service the client Typically this is STRATEGY, CLIENT SERVICE AND CREATIVE This Triad leads collectively and with equal authority and accountability for the client Reporting Lines VML SA is a matrix organisation Each member of a pod reports in to the POD LEADERSHIP on client and day-to-day work matters; and to a COMMUNITY LEAD in terms of craft, career and performance The Triad equally reports in this way - as a unit they report to Exco directly on client matters; and each Triad member reports to the Community Leader (e.g ECD reports to the Chief Creative Officer) on craft issues An Example For example if we are servicing WILD SUNSCREEN as a client the Wild Sunscreen pod will be made up of 10 dedicated people who do nothing other than service that client In addition there are 10 other people who work a percentage of their time, consistently, on this client', '[-0.0059198225,0.031861957,0.06904825,0.016225217,0.031161385,0.047919035,0.018256873,0.010354435,0.0023609232,-0.02517851,0.053831853,-0.029536061,0.03544888,-0.042146333,-0.0076152035,-0.013801243,0.014172546,-0.09707108,-0.037690703,0.018677216,0.03379553,0.053159304,0.025010375,0.046798125,-0.015706796,0.023202902,-0.032534502,0.041669946,-0.018046701,-0.019798128,0.070169166,-0.021437464,-0.010746755,0.0101442635,-0.019489877,0.0074961064,0.009716916,0.055737406,-0.010564607,0.025654899,0.031049294,0.025528796,0.007685261,0.03567306,0.028359102,-0.013605083,-0.017472234,0.013696157,0.03071302,0.029451992,0.0037270363,0.05072132,0.021339385,0.04337934,-0.05996885,0.019826151,0.03673793,0.007958483,0.006536325,0.024842238,0.02744836,0.013464969,0.040100668,0.014515826,0.01594499,-0.016225217,-0.033515304,-0.0016507198,-0.0