INSERT INTO policy_embeddings (id, policy_id, policy_slug, chunk_index, content, embedding, created_at) VALUES (189, '3b511330-0a67-4284-8378-d2ed534894b4', 'business-structure', 2, 'The pod is lead by an Executive Creative Director, a Client Partner and a Strategy Director They focus on thinking ahead for what the client needs, guiding the work to deliver on the client''s objectives and leading the team in that delivery Individuals within the team will report into their discipline lead in the Triad (e.g Creative reports to the ECD) but also into the Triad as a unit in terms of any client-related work That same Creative will also report into the the Chief Creative Officer as the Community Lead for the Creative team This table explains the different kinds of issues individuals will report to each of these reporting lines for', '[0.028704619,0.010447354,0.06785659,0.00045931232,0.0074962326,0.042608816,0.030650694,0.02294321,-0.008315633,-0.028320525,0.062018365,-0.021688502,-0.0033736248,-0.03321132,-0.019076664,-0.012860744,-0.0071249423,-0.094538316,0.010818645,0.023775414,0.022559116,0.052902535,0.041046835,0.046808243,-0.022802375,0.008001956,-0.014262687,0.048523866,-0.0048619886,-0.0020164931,0.06273534,-0.020203339,-0.028166886,0.0018468515,-0.0020132922,-0.019704018,-0.0021125164,0.036181647,-0.0016836117,0.015043678,0.03574634,0.02277677,-0.009525529,0.013955412,0.008789349,-0.02711703,-0.022034187,-0.00347605,0.029498413,0.05382436,0.0064143683,0.07922577,0.050700396,0.0045515127,-0.05915046,0.03377466,0.032980863,-0.0078611225,0.037333928,0.027680367,0.053875573,0.01688733,0.028038856,0.011228345,0.008520483,-0.030112963,-0.044478074,0.014505947,0.005873436,-0.024722844,0.08275943,0.053926785,-0.011023495,-0.03088115,-0.025209364,-0.036924228,0.0015291739,-0.028499769,0.008085177,-0.019575987,0.022725556,-0.029805688,0.03902394,-0.013020784,-0.008290027,-0.030420238,0.010498567,-0.029600838,-0.013161618,0.0081683975,-0.021765321,0.020459402,-0.017168999,0.